# 產生 src/places.js：命造代碼「出生地」對照（繁體名稱＋別名；附繁→簡字表供比對）
import json, re, subprocess, opencc
cc = opencc.OpenCC('t2s')
base = json.loads(subprocess.run(['node', '-e', "import('./src/cities.js').then(m=>console.log(JSON.stringify(m.CITIES.flatMap(([g,cs])=>cs.map(c=>[c[0],c[2]])))))"], capture_output=True, text=True).stdout)
P = []
for n, lon in base:
    names = [n] + [x for x in re.split(r'[（）()]', n) if x]
    P.append((names, lon))
