for item in EXTRA.split('|'):
    parts = item.split(); lon = float(parts[-1]); names = parts[:-1]
    nn = []
    for n in names: nn += [n] + [x for x in re.split(r'[（）()]', n) if x]
    P.append((nn, lon))
chars = sorted({c for names, _ in P for n in names for c in n} | set('臺灣縣區鄉鎮國'))
t2s = {c: cc.convert(c) for c in chars if cc.convert(c) != c}
t2s['臺'] = '台'
js = "// 自動產生（tests/gen-places.py）：命造代碼出生地 → 經度。名稱含本站城市選單與常用台灣、大陸、港澳、各國城市；比對時繁簡互通。\n"
js += "export const PLACES = " + json.dumps([[n, l] for n, l in P], ensure_ascii=False) + ";\n"
js += "export const T2S = " + json.dumps(''.join(k + v for k, v in t2s.items()), ensure_ascii=False) + ";\n"
open('src/places.js', 'w').write(js); print(len(P), 'places', len(t2s), 'chars')
